steps.script:
try {
$d='C:\TTiTTulares\image-approval-receipts'
$f=@('tr-img-auto-3b5034f473ba-r0-a1-1794458225789.json','tr-img-auto-5e5af80baed0-r0-a1-1794458225789.json','tr-img-auto-88e514ece616-r0-a1-1794458225789.json','tr-img-auto-95b49291de75-r0-a1-1794458225789.json','tr-img-auto-ba7633699cd1-r0-a1-1794458225790.json','tr-img-auto-ba9b353684f9-r0-a1-1794458225790.json','tr-img-auto-cf2df84a5714-r0-a1-1794458225790.json','tr-img-auto-e386f83a422f-r0-a1-1794458225790.json','tr-img-auto-ea81ac388672-r0-a1-1794458225790.json','tr-img-auto-f3c37f45aebd-r0-a1-1794458225791.json','tr-img-auto-40ae1da9ecb1-r0-a1-1794458225791.json','tr-img-auto-69beea7215d2-r0-a1-1794458225791.json','tt-img-auto-71bb196c625c-r1-a1-1794456625661.json')
$ok=0;$pending=0;$missing=@();$states=@()
foreach($n in $f) {
 $p=Join-Path $d $n
 if(-not (Test-Path -LiteralPath $p)){$missing+=$n;continue}
 try{$j=Get-Content -LiteralPath $p -Raw|ConvertFrom-Json
 if($j.id -and ([string]$j.rasterSHA256).Length -eq 64){$ok++}
 if([string]$j.state -eq 'pending'){$pending++}
 else{$states+=([string]$j.state)}
 }catch{$states+='invalid_json'}
}
Write-Output ('TTRESULT:'+(@{total=$f.Count;valid=$ok;pending=$pending;missing=$missing;other=$states}|ConvertTo-Json -Compress -Depth 3))
}catch{Write-Output ('TTRESULT:'+(@{error=$_.Exception.Message}|ConvertTo-Json -Compress))}
